(39711, 'Psalms 17:5', 'Psalms', 17, 5, 'یمه تللی همېشه د ستا په لاره ښویېدلي مې هېڅ نه دي قدمونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms17_verse_5.mp3', '', 1761754199, 1761754199),
(39712, 'Psalms 17:6', 'Psalms', 17, 6, 'خدایه فریاد کومه ځکه راکوې ته ځواب ونیسه غوږ ماته واوره زما بیان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms17_verse_6.mp3', '', 1761754199, 1761754199),
(39713, 'Psalms 17:7', 'Psalms', 17, 7, 'عجیبه او تلپاتې مینه دې ښکاره کړه ماته ژغوري ستا ځواکمن لاس هغوی چې پناه غواړي په تا کې له دښمنه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms17_verse_7.mp3', '', 1761754199, 1761754199),
(39714, 'Psalms 17:8', 'Psalms', 17, 8, 'ومې ساته لکه کسي د چشمانو پټ مې کړه د سیوري د وزرو نه دې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms17_verse_8.mp3', '', 1761754199, 1761754199),
(39715, 'Psalms 17:9', 'Psalms', 17, 9, 'ومې ساته له بد کارو چې حمله کوي په ما له قاتلو دښمنانو چې چاپېره دي له ما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms17_verse_9.mp3', '', 1761754199, 1761754199),
(39716, 'Psalms 17:10', 'Psalms', 17, 10, 'رحم نشته په هغوی کې کړي خبرې کبرجنې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms17_verse_10.mp3', '', 1761754199, 1761754199),
(39717, 'Psalms 17:11', 'Psalms', 17, 11, 'په ما پسې دي هغوی چاپېر شوي دي له ما نه په هرځای کې چې زه ګرځم دوی فرصت ته انتظار کړي چې ما وولي په ځمکه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms17_verse_11.mp3', '', 1761754199, 1761754199),
(39718, 'Psalms 17:12', 'Psalms', 17, 12, 'دوی په شان دي د هغو وږیو زمریانو چې کړي ښکار خوراک دپاره یا په مثل د زمریانو د بچیانو چې په پټ ځای کې وي ناست حملې دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms17_verse_12.mp3', '', 1761754199, 1761754199),
(39719, 'Psalms 17:13', 'Psalms', 17, 13, 'ای څښتنه، شه راپورته مقابل کې ته زما د دښمنانو او دوی مات کړه له بدکارو مې کړه خلاص په توره خپله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms17_verse_13.mp3', '', 1761754199, 1761754199),
(39720, 'Psalms 17:14', 'Psalms', 17, 14, 'چې هرڅه لري هغوی په دې دنیا کې ما کړه خلاص له داسې خلکو سزا ورکړه د کړاو چې تا ساتلی دوی دپاره هم ورکړه پرېمانه کړاوونه یې بچیانو ته دغه شانتې ورکړه کړاوونه د بچیانو اولادو ته یې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms17_verse_14.mp3', '', 1761754199, 1761754199),
(39721, 'Psalms 17:15', 'Psalms', 17, 15, 'خو زه به وکړم ستا دیدار ځکه بد مې کړي نه دي او چې کله رابېدار شم موجودیت د ستا قانع به زما زړه کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms17_verse_15.mp3', '', 1761754199, 1761754199),
(39722, 'Jeremiah 3:1', 'Jeremiah', 3, 1, 'مالِک خُدائ فرمائى، ”کۀ يو سړے خپله ښځه طلاقه کړى او د هغۀ نه جدا شى او بيا هغه د بل چا سره وادۀ وکړى نو آيا بيا اول خاوند ته د دې سره د دوباره وادۀ کولو اجازت شته څۀ؟ بلکل نه، ولې چې په داسې کولو به ټوله زمکه پوره پليته نۀ شى څۀ؟ خو اے اِسرائيله لکه څنګه چې يوه زناکاره ښځه په ډېرو سړو پسې ګرځى دغه شان تاسو په ډېرو بُتانو پسې وګرځېدئ نو اوس تاسو غواړئ چې ما ته دوباره راشئ څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_1.mp3', '', 1761754199, 1761754199),
(39723, 'Jeremiah 3:2', 'Jeremiah', 3, 2, 'د اوچتو خُشکو غرونو طرف ته نظر وکړه او وګوره چې آيا هلته په هغې کښې داسې ځائ شته چې تۀ په کښې بې‌حرمته شوے نۀ يې؟ د لارې په خوا کښې تۀ د زنا دپاره يارانو ته داسې ولاړه وې، لکه چې يو کوچے په صحرا کښې په انتظار ناست وى. تا د زناکارۍ او شرارت په وجه ټوله زمکه پليته کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_2.mp3', '', 1761754199, 1761754199),
(39724, 'Jeremiah 3:3', 'Jeremiah', 3, 3, 'نو باران په دې وجه ايسار شوے وو او د سپرلى څاڅکى ونۀ ورېدل. نو دا چې تا د کنجرى شکل نيولے دے او تا له هيڅ شرم نۀ درځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_3.mp3', '', 1761754199, 1761754199),
(39725, 'Jeremiah 3:4', 'Jeremiah', 3, 4, 'تۀ د دومره بې‌شرمۍ باوجود بيا هم ما ته وائې چې، ”اے پلاره، کله چې زۀ وړه وم، تا ما سره مينه کوله،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_4.mp3', '', 1761754199, 1761754199),
(39726, 'Jeremiah 3:5', 'Jeremiah', 3, 5, 'ولې تۀ به د تل دپاره ما ته په قهر يې څۀ؟ ولې ستا غضب به د تل دپاره په مونږ باندې وى څۀ؟“ تۀ خو داسې وائې مګر څومره بدعملى چې تا نه کېدے شى دومره کوې.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_5.mp3', '', 1761754199, 1761754199),
(39727, 'Jeremiah 3:6', 'Jeremiah', 3, 6, 'د يوسياه بادشاه د حکومت په دوران کښې مالِک خُدائ ما ته وفرمائيل، ”تا هغه څۀ وليدل کوم چې بې‌وفا اِسرائيل کړى دى؟ لکه د يوې بدکارې ښځې په شان هغې په هر يو اوچت غرۀ او د هرې شنې ونې د سورى لاندې زنا کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_6.mp3', '', 1761754199, 1761754199),
(39728, 'Jeremiah 3:7', 'Jeremiah', 3, 7, 'زما خيال دا وو چې د دې هر څۀ کولو نه وروستو به هغه ما ته واپس راوګرځى. خو دا راونۀ ګرځېده او د دې بې‌وفا خور يهوداه دا هر څۀ وليدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_7.mp3', '', 1761754199, 1761754199),
(39729, 'Jeremiah 3:8', 'Jeremiah', 3, 8, 'ما بې‌وفا اِسرائيل ته د هغې د زناکارۍ په وجه طلاق نامه ورکړه او ومې شړله نو بيا ما وليدل چې د هغې خور يهوداه نۀ يرېدله. هغه هم بهر ووتله او زناکارى يې شروع کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_8.mp3', '', 1761754199, 1761754199),
(39730, 'Jeremiah 3:9', 'Jeremiah', 3, 9, 'ځکه چې د اِسرائيل دغه بدکارى هغې ته ډېره بې‌اهميته ښکارېده نو هغې هغه زمکه پليته کړه چې د کاڼو او لرګو د بُتانو سره يې زنا شروع کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_9.mp3', '', 1761754199, 1761754199),
(39731, 'Jeremiah 3:10', 'Jeremiah', 3, 10, 'خو د دې هر څۀ باوجود، د هغې بې‌وفا خور يهوداه ما ته په پوره زړۀ سره راونۀ ګرځېدله، خو صرف په ظاهرى شکل سره زما طرف ته راواپس شوه. دا د مالِک خُدائ فرمان دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_10.mp3', '', 1761754199, 1761754199),
(39732, 'Jeremiah 3:11', 'Jeremiah', 3, 11, 'نو بيا مالِک خُدائ ما ته وفرمائيل چې، ”خو بيا دا چې بې‌ايمانه اِسرائيل د دوکه باز يهوداه نه صادق دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_11.mp3', '', 1761754199, 1761754199),
(39733, 'Jeremiah 3:12', 'Jeremiah', 3, 12, 'هغۀ ما ته وفرمائيل چې، ”د شمال طرف ته لاړ شه او هغوئ ته ووايه، اے بې‌ايمانه اِسرائيله، مالِک خُدائ فرمائى ما ته راواپس شه. زۀ به په غصې سره نور تا ته نۀ ګورم، ځکه چې زۀ رحم کوونکے يم، مالِک خُدائ فرمائى، او نۀ به زۀ د تل دپاره تا ته غصه يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_12.mp3', '', 1761754199, 1761754199),
(39734, 'Jeremiah 3:13', 'Jeremiah', 3, 13, 'تۀ صرف د خپلو ګناهونو اقرار وکړه چې ګناهګار يم او تا د خپل مالِک خُدائ خلاف سرکشى کړې ده، او تا د هرې شنې ونې د لاندې د پردو بُتانو عبادت کړے دے او زما د کلام تابعدارى دې نۀ ده کړې، مالِک خُدائ دا فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_13.mp3', '', 1761754199, 1761754199),
(39735, 'Jeremiah 3:14', 'Jeremiah', 3, 14, 'اے بې‌ايمانه خلقو، راواپس شئ ځکه چې زۀ ستاسو مالِک يم. زۀ به ستاسو د ښاريې نه يو او د هرې قبيلې نه دوه دوه کسان خوښ کړم او صيون ښار ته به مو واپس راولم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_14.mp3', '', 1761754199, 1761754199),
(39736, 'Jeremiah 3:15', 'Jeremiah', 3, 15, 'زۀ به تاسو له د شپونکو په شان مشران درکړم چې زما سوچ لرى او تاسو ته په عِلم او عقل سره هدايت کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_15.mp3', '', 1761754199, 1761754199),
(39737, 'Jeremiah 3:16', 'Jeremiah', 3, 16, 'نو کله چې ستاسو د خلقو شمېر په هغه مُلک کښې ډېر شى، مالِک خُدائ فرمائى، نو تاسو به په هغه ورځو کښې د خُدائ د لوظ صندوق ذکر نۀ کوئ او هم به ستاسو خيال ته دا نور نۀ راځى، او نۀ به هغه يادوئ، او نۀ به د هغې د ضرورت احساس تاسو ته کيږى، او نۀ به هغه دوباره جوړ کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_16.mp3', '', 1761754199, 1761754199),
(39738, 'Jeremiah 3:17', 'Jeremiah', 3, 17, 'نو په دغه وخت کښې به دوئ يروشلم ته د ”مالِک خُدائ تخت“ ووائى، او ټول قومونه به په يروشلم کښې راټول شى او د مالِک خُدائ نوم له به عزت ورکړى. او دوئ به نور د خپل سرکشه او شريره زړونو پيروى نۀ کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_17.mp3', '', 1761754199, 1761754199),
(39739, 'Jeremiah 3:18', 'Jeremiah', 3, 18, 'نو په دغه ورځو کښې به د يهوداه خاندان د اِسرائيل د خاندان سره يوځائ شى او په شريکه به دوئ د شمال د جلاوطنۍ د مُلک نه هغه مُلک ته واپس راشى کوم چې ما ستاسو پلار نيکۀ له په ميراث کښې ورکړے وو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_18.mp3', '', 1761754199, 1761754199),
(39740, 'Jeremiah 3:19', 'Jeremiah', 3, 19, '”مالِک خُدائ په خپله فرمائى چې اے بنى اِسرائيله، ما غوښتل چې زۀ تا سره د خپل بچى په شان سلوک وکړم او د خپلې خوښې مُلک او زمکه درکړم، چې د نورو مُلکونو په نسبت ښکلې او شانداره وى. زما دا خيال وو چې تۀ به ما ته خپل پلار ووائې او زما نه به وانۀ وړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_19.mp3', '', 1761754199, 1761754199),
(39741, 'Jeremiah 3:20', 'Jeremiah', 3, 20, 'خو تۀ ما سره بې‌وفا شوې د هغې ښځې په شان څوک چې خپل خاوند سره بې‌وفا وى. مالِک خُدائ دا فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_20.mp3', '', 1761754199, 1761754199),
(39742, 'Jeremiah 3:21', 'Jeremiah', 3, 21, 'د خُشکو غرونو په اوچتو سرونو باندې د بنى اِسرائيليانو د ژړا او فرياد شور اورېدلے شى، ځکه چې هغوئ غلطه لار اختيار کړې ده او خپل مالِک خُدائ يې هېر کړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_21.mp3', '', 1761754199, 1761754199),
(39743, 'Jeremiah 3:22', 'Jeremiah', 3, 22, 'اے بې‌وفا بچو ما ته راواپس شئ زۀ به ستاسو بې‌وفائى له شفا درکړم. اے مالِکه خُدايه، مونږ به تا ته راواپس کيږُو ځکه چې تۀ مالِک خُدائ زمونږ خُدائ پاک يې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_22.mp3', '', 1761754199, 1761754199),
(39744, 'Jeremiah 3:23', 'Jeremiah', 3, 23, 'مونږ چې په زور شور سره د غرونو او غونډو په سرونو د بُتانو کوم عبادت کړے دے دا په رښتيا سره دوکه وه، د بنى اِسرائيل خلاصون په يقين سره صرف په مالِک خُدائ زمونږ خُدائ پاک دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_23.mp3', '', 1761754199, 1761754199),
(39745, 'Jeremiah 3:24', 'Jeremiah', 3, 24, 'د اول نه تر آخره پورې دې شرمناک د بعل بُت زمونږ د پلار نيکۀ د محنت مېوه، د دوئ رمې او څاروى، زامن او لوڼه ټول قبضه کړى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_24.mp3', '', 1761754199, 1761754199),
(39746, 'Jeremiah 3:25', 'Jeremiah', 3, 25, 'مونږ له په کار دى چې بې‌عزتى او شرم قبول کړُو او په شرمونو پټ شُو. ځکه چې مونږ د خپل پلار نيکۀ سره د خپل مالِک خُدائ زمونږ خُدائ پاک په خلاف ګناه کړې ده. د اول نه تر آخره پورې مونږ د خپل مالِک خُدائ پيروى نۀ ده کړې.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah3_verse_25.mp3', '', 1761754199, 1761754199),
(39747, 'Judges 8:1', 'Judges', 8, 1, 'د افرایم خلکو جدعون ته وویل: «تا ولې زمونږ سره داسې چلند وکړ؟ تا ولې مونږ د مدیانیانو سره د جګړې په وخت کې راونه غوښتلو؟» او هغه یې سخت ملامت کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_1.mp3', '', 1761754199, 1761754199),
(39748, 'Judges 8:2', 'Judges', 8, 2, 'خو جدعون په ځواب کې وویل: «ما چې کوم کار کړی دی هغه ستاسو د کار په پرتله هېڅ هم نه دی. حتی هغه وړوکی کار چې تاسو د افرایم خلکو کړی دی، هغه زمونږ د ټولې طایفې د کارونو څخه زیات ارزښت لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_2.mp3', '', 1761754199, 1761754199),
(39749, 'Judges 8:3', 'Judges', 8, 3, 'تاسو د خدای په مرسته د مدیانیانو دوه مشران یعنې غراب او زیب ووژل. ما څه کړي دي چې ستاسو سره یې پرتله کړم؟» په دې خبره د هغوی قهر سوړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_3.mp3', '', 1761754199, 1761754199),
(39750, 'Judges 8:4', 'Judges', 8, 4, 'وروسته بیا جدعون د خپلو درې سوه کسانو سره د اردن د سیند څخه تېر شو. که څه هم هغوی ډېر ستومانه شوي وو، خو بیاهم د خپلو دښمنانو پسې وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_4.mp3', '', 1761754199, 1761754199),
(39751, 'Judges 8:5', 'Judges', 8, 5, 'کله چې هغوی سوکوت ته ورسېدل، جدعون د ښارګوټي خلکو ته وویل: «مهرباني وکړئ زما کسانو ته د خوړلو دپاره یو څه ورکړئ. هغوی ډېر ستړي دي، خو مونږ د مدیانیانو پاچاهان زبح او صلمونع تعقیبوو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_5.mp3', '', 1761754199, 1761754199),
(39752, 'Judges 8:6', 'Judges', 8, 6, 'خو د سوکوت مشرانو وویل: «تاسو تر اوسه پورې زبح او صلمونع نه دي نیولي، نو مونږ ولې ستا لښکرو ته ډوډۍ ورکړو؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_6.mp3', '', 1761754199, 1761754199),
(39753, 'Judges 8:7', 'Judges', 8, 7, 'جدعون وویل: «ښه ده! کله چې څښتن زبح او صلمونع ماته په لاس راکړل، نو بیا به زه بېرته راشم او ستاسو غوښې به د صحرا په اغزیو باندې وشکوم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_7.mp3', '', 1761754199, 1761754199),
(39754, 'Judges 8:8', 'Judges', 8, 8, 'جدعون د هغه ځای څخه فنوعیل ته لاړ او د هغه ځای د خلکو څخه یې خواړه وغوښتل، خو د فنوعیل خلکو هم د سوکوت د خلکو په شان هغه ته ځواب ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_8.mp3', '', 1761754199, 1761754199),
(39755, 'Judges 8:9', 'Judges', 8, 9, 'جدعون د فنوعیل خلکو ته وویل: «کله چې زه په سلامتۍ سره بېرته راشم، نو ستاسو برج به راوغورځوم!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_9.mp3', '', 1761754199, 1761754199),
(39756, 'Judges 8:10', 'Judges', 8, 10, 'په دې وخت کې زبح او صلمونع شاوخوا د پنځلس زره عسکرو سره په قرقور کې وو. د دښتې د قومونو د ټولو لښکرو څخه یوازې همدومره کسان پاتې شوي وو، ځکه چې یو لک او شل زره عسکر په جګړه کې وژل شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_10.mp3', '', 1761754199, 1761754199),
(39757, 'Judges 8:11', 'Judges', 8, 11, 'جدعون د کاروان د تېرېدلو په لاره باندې چې د نوبح او یجبها په ختیځ کې وه، لاړ او ناڅاپه یې د مدیانیانو په لښکرو باندې حمله وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_11.mp3', '', 1761754199, 1761754199),
(39758, 'Judges 8:12', 'Judges', 8, 12, 'د مدیانیانو دوه پاچاهان زبح او صلمونع وتښتېدل، خو جدعون په هغوی پسې شو، ویې نیول او د هغوی ټول لښکر یې سخت وارخطا کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_12.mp3', '', 1761754199, 1761754199),
(39759, 'Judges 8:13', 'Judges', 8, 13, 'د جګړې څخه وروسته جدعون کور ته روان شو. هغه د حارس په غاښي باندې روان ؤ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_13.mp3', '', 1761754199, 1761754199),
(39760, 'Judges 8:14', 'Judges', 8, 14, 'او یو ځوان یې چې د سوکوت اوسېدونکی ؤ، ونیوه او پوښتنه یې ترې وکړه چې د سوکوت مامورین او سپین ږیري څوک دي. هغه ځوان ورته د سوکوت د اووه اویا کسانو نومونه ولیکل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_14.mp3', '', 1761754199, 1761754199),
(39761, 'Judges 8:15', 'Judges', 8, 15, 'بیا جدعون لاړ او د سوکوت خلکو ته یې وویل: «تاسو ماته پېغور راکاوه او ویل مو چې تا تر اوسه پورې زبح او صلمونع نه دي نیولي، نو مونږ ولې ستاسو ستړي شویو لښکرو ته ډوډۍ ورکړو؟ دا دی وګورئ زبح او صلمونع دلته دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_15.mp3', '', 1761754199, 1761754199),
(39762, 'Judges 8:16', 'Judges', 8, 16, 'بیا هغه د دښتې اغزي راواخیستل او د سوکوت مشران یې په اغزیو باندې ووهل او سزا یې ورته ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_16.mp3', '', 1761754199, 1761754199),
(39763, 'Judges 8:17', 'Judges', 8, 17, 'همدارنګه هغه د فنوعیل برج وران کړ او د ښارګوټي ټول سړي یې ووژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_17.mp3', '', 1761754199, 1761754199),
(39764, 'Judges 8:18', 'Judges', 8, 18, 'بیا هغه د زبح او صلمونع څخه پوښتنه وکړه: «هغه خلک چې تاسو په تابور کې ووژل، هغه څه ډول خلک وو؟» هغوی په ځواب کې وویل: «هغوی ستا په شان وو، هر یو لکه د شاهزاده په شان ؤ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_18.mp3', '', 1761754199, 1761754199),
(39765, 'Judges 8:19', 'Judges', 8, 19, 'جدعون وویل: «هغوی زما سکه ورونه وو. زه د ژوندي څښتن په نوم قسم خورم، که چېرې تاسو هغوی نه وای وژلي، نو ما به هم تاسو نه وای وژلي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_19.mp3', '', 1761754199, 1761754199),
(39766, 'Judges 8:20', 'Judges', 8, 20, 'بیا هغه خپل مشر زوی یتر ته وویل: «پورته شه او هغوی ووژنه!» خو هغه خپله توره راونه ویستله، ځکه چې هغه لا هلک ؤ او ووېرېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_20.mp3', '', 1761754199, 1761754199),
(39767, 'Judges 8:21', 'Judges', 8, 21, 'بیا زبح او صلمونع جدعون ته وویل: «راشه ته په خپله مونږ ووژنه. د هلک څخه د سړي کار مه غواړه.» نو جدعون هغوی دواړه ووژل او کوم زېورات چې د هغوی د اوښانو په غاړو کې وو، هغه یې واخیستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_21.mp3', '', 1761754199, 1761754199),
(39768, 'Judges 8:22', 'Judges', 8, 22, 'له هغې وروسته اسراییلیانو جدعون ته وویل: «ته زمونږ پاچا شه او ستا څخه وروسته دې ستا اولاده په مونږ باندې پاچاهي وکړي، ځکه چې تا مونږ له مدیانیانو څخه ژغورلي یو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_22.mp3', '', 1761754199, 1761754199),
(39769, 'Judges 8:23', 'Judges', 8, 23, 'جدعون په ځواب کې وویل: «نه به زه او نه به زما زوی ستاسو پاچا شي. څښتن به ستاسو پاچا وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_23.mp3', '', 1761754199, 1761754199),
(39770, 'Judges 8:24', 'Judges', 8, 24, 'خو زه ستاسو څخه یوه غوښتنه کوم. تاسو هر یو ماته د خپل غنیمت څخه یوه یوه غوږوالۍ راکړئ.» هغه داسې وویل، ځکه چې د دښمن عسکر چې اسماعیلیان وو، د سرو زرو غوږوالۍ به یې اچولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_24.mp3', '', 1761754199, 1761754199),
(39771, 'Judges 8:25', 'Judges', 8, 25, 'خلکو په ځواب کې وویل: «مونږ په خوشحالۍ سره خپلې غوږوالۍ تاته درکوو.» نو هغوی یوه چپنه وغوړوله او هر کس په کې خپلې غوږوالۍ چې په غنیمت کې یې نیولې وې، واچولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_25.mp3', '', 1761754199, 1761754199),
(39772, 'Judges 8:26', 'Judges', 8, 26, 'د سرو زرو د غوږوالیو وزن چې جدعون واخیستلې شل کیلو ګرامه ؤ، پرته له ګاڼو، غاړکیو او د مدیانیانو د پاچاهانو د شاهانه کالیو او هغو زنځیرونو څخه چې د هغوی د اوښانو په غاړو کې وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_26.mp3', '', 1761754199, 1761754199),
(39773, 'Judges 8:27', 'Judges', 8, 27, 'جدعون د هغو سرو زرو څخه یو بت جوړ کړ او هغه یې په خپل ښارګوټي یعنې عفره کې کېښود. ټولو اسراییلیانو خدای پرېښود او د بت د عبادت دپاره هلته لاړل. دا کار د جدعون او د هغه د کورنۍ دپاره یو دام شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_27.mp3', '', 1761754199, 1761754199),
(39774, 'Judges 8:28', 'Judges', 8, 28, 'نو مدیانیان د اسراییلیانو په وړاندې کمزوري شول او نور یې نه شو کولای چې سر راپورته کړي. د جدعون په ژوندانه کې څلوېښت کاله په هغه خاوره کې ارامي وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_28.mp3', '', 1761754199, 1761754199),
(39775, 'Judges 8:29', 'Judges', 8, 29, 'جدعون بېرته خپل کور ته ستون شو او هلته اوسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_29.mp3', '', 1761754199, 1761754199),
(39776, 'Judges 8:30', 'Judges', 8, 30, 'جدعون اویا زامن درلودل، ځکه چې ډېرې ښځې یې درلودلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_30.mp3', '', 1761754199, 1761754199),
(39777, 'Judges 8:31', 'Judges', 8, 31, 'هغه یوه وینځه هم درلودله چې په شکیم کې اوسېدله، هغې هم د هغه دپاره یو زوی وزېږاوه او جدعون ورباندې ابیملک نوم کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_31.mp3', '', 1761754199, 1761754199),
(39778, 'Judges 8:32', 'Judges', 8, 32, 'جدعون د یوآش زوی په پوخ عمر کې مړ شو او د خپل پلار په هدیره کې یې په عفره یعنې د ابیعزر د طایفې په ښارګوټي کې ښخ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_32.mp3', '', 1761754199, 1761754199),
