(39780, 'Judges 8:34', 'Judges', 8, 34, 'او خپل څښتن خدای یې چې هغوی یې د خپل شاوخوا ټولو دښمنانو څخه ژغورلي وو، هېر کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_34.mp3', '', 1761754199, 1761754199),
(39781, 'Judges 8:35', 'Judges', 8, 35, 'سره له دې چې یروبعل (جدعون) د اسراییلیانو دپاره ښه ښه کارونه کړي وو، خو هغوی د هغه د کورنۍ سره وفاداري ونه ښودله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges8_verse_35.mp3', '', 1761754199, 1761754199),
