(39785, 'Exodus 29:4', 'Exodus', 29, 4, 'بیا هارون او د هغه زامن د سپېڅلې خېمې د دروازې خولې ته راوله او غسل ورته ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_4.mp3', '', 1761754199, 1761754199),
(39786, 'Exodus 29:5', 'Exodus', 29, 5, 'دا کالي واخله او هارون ته یې ورواغونده: کمیس، هغه چپنه چې د سپېڅلي پېشبند لاندې اغوستل کیږي، سپېڅلی پېشبند او سینه پوښ. سپېڅلی پېشبند په کمربند باندې وتړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_5.mp3', '', 1761754199, 1761754199),
(39787, 'Exodus 29:6', 'Exodus', 29, 6, 'هغه ته لونګۍ په سر کړه او په هغې لونګۍ باندې سپېڅلی نښان ولګوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_6.mp3', '', 1761754199, 1761754199),
