(39789, 'Exodus 29:8', 'Exodus', 29, 8, 'د هغه زامن راوله او کمیسونه ورته واغونده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_8.mp3', '', 1761754199, 1761754199),
(39790, 'Exodus 29:9', 'Exodus', 29, 9, 'او خولۍ ګانې ورته په سر کړه. بیا د هارون او د هغه د زامنو په ملاګانو باندې پټۍ ګانې وتړه. په دې ډول به هارون او د هغه زامن وټاکې. هغوی او د هغوی اولاده به د تل دپاره د کاهنانو په توګه زما خدمت کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_9.mp3', '', 1761754199, 1761754199),
(39791, 'Exodus 29:10', 'Exodus', 29, 10, 'غویی د سپېڅلې خېمې مخې ته راوله او هارون او د هغه زامن به د هغه په سر باندې خپل لاسونه کېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_10.mp3', '', 1761754199, 1761754199),
(39792, 'Exodus 29:11', 'Exodus', 29, 11, 'هغه د خېمې د دروازې په خوله کې زما په حضور کې حلال کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_11.mp3', '', 1761754199, 1761754199),
(39793, 'Exodus 29:12', 'Exodus', 29, 12, 'د غویي لږه وینه واخله او په خپله ګوته یې په هغو ښکرونو باندې چې د قربانۍ د ځای په کنجونو کې دي وسولوه. بیا پاتې وینه د قربانۍ د ځای په بېخ کې توی کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_12.mp3', '', 1761754199, 1761754199),
(39794, 'Exodus 29:13', 'Exodus', 29, 13, 'بیا ټوله هغه وازګه چې په کولمو باندې پرته وي، د اینې ډېره ښه برخه او د هغه دوه پښتورګي چې وازګه ورباندې پرته وي، واخله او هغه ماته د یوې نذرانې په توګه د قربانۍ په ځای باندې وسوځوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_13.mp3', '', 1761754199, 1761754199),
(39795, 'Exodus 29:14', 'Exodus', 29, 14, 'خو د غویي غوښه، پوستکی او خوشایي د کمپ څخه دباندې وسوځوه. دا د ګناه یوه نذرانه ده چې د کاهنانو د ګناهونو د پاکولو دپاره ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_14.mp3', '', 1761754199, 1761754199),
(39796, 'Exodus 29:15', 'Exodus', 29, 15, 'د هغو پسونو څخه یو پسه واخله او هارون او د هغه زامن به خپل لاسونه د هغه په سر باندې کېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_15.mp3', '', 1761754199, 1761754199),
(39797, 'Exodus 29:16', 'Exodus', 29, 16, 'هغه حلال کړه او وینه یې واخله او د قربانۍ د ځای په څلورو خواو باندې یې وشینده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_16.mp3', '', 1761754199, 1761754199),
(39798, 'Exodus 29:17', 'Exodus', 29, 17, 'پسه ټوټې ټوټې کړه او د نس دنننۍ برخې او پښې یې ووینځه او د سر او د نورو ټوټو سره یې کېږده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_17.mp3', '', 1761754199, 1761754199),
(39799, 'Exodus 29:18', 'Exodus', 29, 18, 'بیا ټول پسه د قربانۍ په ځای باندې وسوځوه. دا زما یعنې څښتن دپاره یوه سوځېدونکې نذرانه ده چې بوی یې په ما باندې ښه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_18.mp3', '', 1761754199, 1761754199),
(39800, 'Exodus 29:19', 'Exodus', 29, 19, 'هغه بل پسه واخله او هارون او د هغه زامن به خپل لاسونه د هغه په سر باندې کېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_19.mp3', '', 1761754199, 1761754199),
(39801, 'Exodus 29:20', 'Exodus', 29, 20, 'هغه حلال کړه. لږه وینه یې واخله او د هارون او د هغه د زامنو د ښي غوږونو په نرمیو، د ښي لاسونو په غټو ګوتو او د ښي پښو په غټو ګوتو باندې یې وسولوه. بیا پاتې وینه د قربانۍ د ځای په څلورو خواو باندې وشینده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_20.mp3', '', 1761754199, 1761754199),
(39802, 'Exodus 29:21', 'Exodus', 29, 21, 'د هغې وینې څخه لږه وینه چې د قربانۍ په ځای باندې پرته ده، واخله او لږ د مسح کولو تېل واخله او په هارون او د هغه په زامنو او د هغوی په کالیو باندې یې وشینده. بیا به هغه، د هغه زامن او د هغوی کالي ماته وقف شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_21.mp3', '', 1761754199, 1761754199),
(39803, 'Exodus 29:22', 'Exodus', 29, 22, 'د پسه وازګه، لم، هغه وازګه چې په کولمو باندې پرته وي، د اینې ډېره ښه برخه، دوه پښتورګي د وازګې سره چې ورباندې پرته وي او ښي ورون، دا ټول ورڅخه پرې کړه. دا پسه د ټاکنې د مراسمو دپاره دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_22.mp3', '', 1761754199, 1761754199),
(39804, 'Exodus 29:23', 'Exodus', 29, 23, 'د هغې ټوکرۍ څخه د هر ډول ډوډۍ نه یوه یوه ډوډۍ راواخله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_23.mp3', '', 1761754199, 1761754199),
(39805, 'Exodus 29:24', 'Exodus', 29, 24, 'او دا ټول د هارون او د هغه د زامنو په لاسونو کې کېږده. بیا هغوی دې هغه پورته ونیسي، ترڅو دا وښایي چې هغه ماته وقف شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_24.mp3', '', 1761754199, 1761754199),
(39806, 'Exodus 29:25', 'Exodus', 29, 25, 'بیا یې د هغوی د لاسونو څخه راواخله او د قربانۍ په ځای باندې یې د سوځېدونکې نذرانې سره وسوځوه چې بوی یې په ما څښتن باندې ښه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_25.mp3', '', 1761754199, 1761754199),
(39807, 'Exodus 29:26', 'Exodus', 29, 26, 'کله چې ته د هارون د ټاکلو دپاره د پسه سینه واخلې، نو لومړی باید هغه پورته ونیسې، ترڅو دا وښایي چې دا غوښه ماته وقف شوې ده. دا به ستا برخه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_26.mp3', '', 1761754199, 1761754199),
(39808, 'Exodus 29:29', 'Exodus', 29, 29, 'د هارون سپېڅلي کالي به د هغه له مرګ څخه وروسته د هغه اولادې ته پاتې شي، ترڅو هغوی په کې مسح شي او وټاکل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_29.mp3', '', 1761754199, 1761754199),
(39809, 'Exodus 29:30', 'Exodus', 29, 30, 'د هارون زوی چې د هغه څخه وروسته کاهن کیږي او سپېڅلې خېمې ته ورننوځي چې په سپېڅلي ځای کې خدمت وکړي، نو هغه دې اووه ورځې دا کالي واغوندي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_30.mp3', '', 1761754199, 1761754199),
(39810, 'Exodus 29:31', 'Exodus', 29, 31, 'هغه پسه چې د ټاکنې د مراسمو دپاره دی، واخله او غوښه یې په یو پاک ځای کې پخه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_31.mp3', '', 1761754199, 1761754199);